    for (const cookie of existingCookies) {
      _res.headers.append('set-cookie', cookie)
    }
  }
  this.#res = _res
  this.finalized = true
}
```

Note: `_res = createResponseInstance(_res.body, _res)` preserves the new Response's own headers (including all Set-Cookie values), so do not delete them.

